type RecvMiddleware func(next RecvEndpoint) RecvEndpoint

// RecvMiddlewareBuilder builds a RecvMiddleware with context.
// Deprecated: Use the new typed streaming middleware builder instead.
type RecvMiddlewareBuilder func(ctx context.Context) RecvMiddleware

// RecvChain connects the middlewares into one middleware.
// Deprecated: Use the new typed streaming middleware chain instead.
func RecvChain(mws ...RecvMiddleware) RecvMiddleware {
	return func(next RecvEndpoint) RecvEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

